parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "qualificationRate": {
      "type": "number",
      "description": "Qualification score between 0.0 and 1.0"
    },
    "status": {
      "type": "string",
      "enum": ["Qualified", "Borderline", "Unqualified"],
      "description": "Recommendation status"
    },
    "targetRole": {
      "type": "string",
      "description": "The evaluated position title"
    },
    "core_checks": {
      "type": "object",
      "description": "Map of core criteria titles to boolean true/false"
    },
    "preferred_checks": {
      "type": "object",
      "description": "Map of preferred criteria titles to boolean true/false"
    },
    "explanation": {
      "type": "string",
      "description": "Detailed point-by-point evidence breakdown"
    }
  },
  "required": [
    "qualificationRate",
    "status",
    "targetRole",
    "explanation"
  ],
  "additionalProperties": false
}
